QB.push(
{id:"l43",d:"lgpd",t:"ce",e:"Cebraspe",q:"O tratamento de dados pessoais cujo acesso é público deve considerar a finalidade, a boa-fé e o interesse público que justificaram sua disponibilização.",a:true,c:"Dado público não é dado livre.",r:"LGPD, art. 7º, §3º"},
{id:"l44",d:"lgpd",t:"ce",e:"Cebraspe",q:"O controlador que obteve consentimento e precisar compartilhar os dados com outros controladores deverá obter consentimento específico do titular para esse fim, ressalvadas as hipóteses de dispensa.",a:true,c:"O consentimento original não se estende automaticamente a outros controladores.",r:"LGPD, art. 7º, §5º"},
{id:"l45",d:"lgpd",t:"ce",e:"Cebraspe",q:"Havendo mudança de finalidade incompatível com o consentimento original, o controlador deve informar previamente o titular, que poderá revogar o consentimento se discordar.",a:true,c:"Literalidade do art. 9º, §2º.",r:"LGPD, art. 9º, §2º"},
{id:"l46",d:"lgpd",t:"ce",e:"Cebraspe",q:"Quando o tratamento for condição para o fornecimento de produto ou serviço, o titular deve ser informado com destaque sobre esse fato e sobre os meios para exercer seus direitos.",a:true,c:"Transparência reforçada.",r:"LGPD, art. 9º, §3º"},
{id:"l47",d:"lgpd",t:"ce",e:"Cebraspe",q:"O consentimento será considerado nulo se as informações fornecidas ao titular tiverem conteúdo enganoso ou abusivo.",a:true,c:"Também é nulo se as informações não forem apresentadas previamente com transparência.",r:"LGPD, art. 9º, §1º"},
{id:"l48",d:"lgpd",t:"me",e:"FGV",q:"O término do tratamento de dados pessoais ocorre nas hipóteses abaixo, EXCETO:",o:["verificação de que a finalidade foi alcançada.","fim do período de tratamento.","comunicação do titular revogando o consentimento, resguardado o interesse público.","determinação da ANPD quando houver violação à LGPD.","solicitação de terceiro interessado na eliminação dos dados."],a:4,c:"O art. 15 não prevê pedido de terceiro como causa de término.",r:"LGPD, art. 15"},
{id:"l49",d:"lgpd",t:"ce",e:"Cebraspe",q:"Os dados de criança coletados sem consentimento, para contatar os pais, podem ser repassados a terceiros desde que para fins de proteção da criança.",a:false,c:"Em nenhum caso podem ser repassados a terceiro sem consentimento.",r:"LGPD, art. 14, §3º"},
{id:"l50",d:"lgpd",t:"ce",e:"Cebraspe",q:"É vedada a comunicação ou o uso compartilhado de dados sensíveis de saúde com objetivo de obter vantagem econômica, salvo, entre outras, nas hipóteses de prestação de serviços de saúde e assistência farmacêutica em benefício dos titulares.",a:true,c:"Exceções voltadas ao interesse do titular.",r:"LGPD, art. 11, §4º"},
{id:"l51",d:"lgpd",t:"ce",e:"Cebraspe",q:"O titular tem o direito de peticionar em relação aos seus dados contra o controlador perante a ANPD.",a:true,c:"Direito previsto no §1º do art. 18 (com reclamação prévia ao controlador, art. 55-J, V).",r:"LGPD, art. 18, §1º"},
{id:"l52",d:"lgpd",t:"ce",e:"Cebraspe",q:"O atendimento aos requerimentos do titular pode ser cobrado, desde que o valor seja informado previamente.",a:false,c:"O requerimento é atendido sem custos para o titular.",r:"LGPD, art. 18, §5º"},
{id:"l53",d:"lgpd",t:"ce",e:"Cebraspe",q:"Quando o tratamento tiver origem no consentimento ou em contrato, o titular pode solicitar cópia eletrônica integral de seus dados, em formato que permita sua utilização subsequente.",a:true,c:"Base para a portabilidade prática.",r:"LGPD, art. 19, §3º"},
{id:"l54",d:"lgpd",t:"ce",e:"Cebraspe",q:"O controlador deve fornecer, sempre que solicitado, informações claras sobre os critérios e procedimentos da decisão automatizada, observados os segredos comercial e industrial.",a:true,c:"Se negar por segredo, a ANPD pode fazer auditoria sobre aspectos discriminatórios.",r:"LGPD, art. 20, §§1º e 2º"},
{id:"l55",d:"lgpd",t:"ce",e:"Cebraspe",q:"Os serviços notariais e de registro exercidos em caráter privado, por delegação do Poder Público, têm o mesmo tratamento dispensado às pessoas jurídicas de direito público.",a:true,c:"Cartórios seguem o regime do Poder Público.",r:"LGPD, art. 23, §4º"},
{id:"l56",d:"lgpd",t:"ce",e:"Cebraspe",q:"O tratamento é irregular quando não fornece a segurança que o titular dele pode esperar, considerados o modo de realização, o resultado, os riscos esperados e as técnicas disponíveis à época.",a:true,c:"Conceito de tratamento irregular.",r:"LGPD, art. 44"},
{id:"l57",d:"lgpd",t:"ce",e:"Cebraspe",q:"O dever de garantir a segurança da informação cessa com o término do tratamento.",a:false,c:"A obrigação permanece mesmo após o término.",r:"LGPD, art. 47"},
{id:"l58",d:"lgpd",t:"ce",e:"Cebraspe",q:"A comunicação de incidente deve mencionar, no mínimo, a natureza dos dados afetados, os titulares envolvidos, os riscos e as medidas adotadas para reverter ou mitigar os efeitos.",a:true,c:"Inclui também as medidas técnicas de segurança e os motivos de eventual demora.",r:"LGPD, art. 48, §1º"},
{id:"l59",d:"lgpd",t:"ce",e:"Cebraspe",q:"Diante de incidente, a ANPD pode determinar ao controlador a ampla divulgação do fato em meios de comunicação.",a:true,c:"Também pode determinar medidas para reverter ou mitigar os efeitos.",r:"LGPD, art. 48, §2º"},
{id:"l60",d:"lgpd",t:"ce",e:"Cebraspe",q:"As sanções da LGPD substituem as sanções administrativas, civis ou penais do Código de Defesa do Consumidor.",a:false,c:"Não substituem; aplicam-se em conjunto.",r:"LGPD, art. 52, §2º"},
{id:"l61",d:"lgpd",t:"ce",e:"Cebraspe",q:"Pessoa jurídica pode ser titular de dados pessoais segundo a LGPD.",a:false,c:"Titular é sempre pessoa natural.",r:"LGPD, art. 5º, V"},
{id:"l62",d:"lgpd",t:"ce",e:"Cebraspe",q:"Para a LGPD, órgão de pesquisa pode ser pessoa jurídica de direito privado com fins lucrativos.",a:false,c:"Órgão de pesquisa é entidade pública ou pessoa jurídica de direito privado sem fins lucrativos.",r:"LGPD, art. 5º, XVIII"},
{id:"l63",d:"lgpd",t:"me",e:"IADES",q:"Uma empresa usa dados de navegação para oferecer produtos semelhantes aos que o cliente comprou, sem pedir consentimento. A base legal mais adequada, observados os requisitos legais, é:",o:["proteção do crédito","legítimo interesse do controlador","tutela da saúde","cumprimento de obrigação legal","exercício regular de direitos em processo arbitral"],a:1,c:"Promoção de atividades do controlador é exemplo de legítimo interesse (art. 10, I), com teste de balanceamento e transparência.",r:"LGPD, art. 10"},
{id:"l64",d:"lgpd",t:"ce",e:"Cebraspe",q:"A ANPD pode dispor sobre padrões de interoperabilidade para fins de portabilidade e sobre o tempo de guarda dos registros.",a:true,c:"Competência normativa expressa.",r:"LGPD, art. 40"},
{id:"a19",d:"anpd",t:"ce",e:"Cebraspe",q:"A ANPD reconheceu a União Europeia como destino com nível adequado de proteção de dados para fins de transferência internacional.",a:true,c:"Res. CD/ANPD 32/2026, primeira decisão de adequação do Brasil.",r:"Res. CD/ANPD 32/2026"},
{id:"a20",d:"anpd",t:"ce",e:"Cebraspe",q:"Com a decisão de adequação da União Europeia, ficou vedado o uso de cláusulas-padrão contratuais para transferências ao bloco.",a:false,c:"A adequação não impede os demais mecanismos de transferência.",r:"Res. CD/ANPD 32/2026"},
{id:"a21",d:"anpd",t:"ce",e:"Cebraspe",q:"A decisão de adequação da União Europeia será reavaliada em quatro anos, com monitoramento contínuo pela ANPD.",a:true,c:"Revisão periódica prevista na própria resolução.",r:"Res. CD/ANPD 32/2026, arts. 3º e 4º"},
{id:"a22",d:"anpd",t:"ce",e:"Cebraspe",q:"O Decreto 12.622/2025 atribuiu à ANPD a competência para zelar pela aplicação do Estatuto Digital da Criança e do Adolescente.",a:true,c:"Depois reforçada pela Lei 15.352/2026.",r:"Decreto 12.622/2025"},
{id:"a23",d:"anpd",t:"ce",e:"Cebraspe",q:"O Mapa de Temas Prioritários 2026–2027 da ANPD inclui, entre seus focos, crianças e adolescentes e inteligência artificial.",a:true,c:"Os quatro focos: direitos dos titulares, crianças e adolescentes, setor público e IA.",r:"Res. CD/ANPD 30/2025"},
{id:"a24",d:"anpd",t:"ce",e:"Cebraspe",q:"A agenda regulatória da ANPD é o instrumento que define as prioridades de fiscalização, enquanto o mapa de temas prioritários define as normas a editar.",a:false,c:"É o contrário: agenda regulatória trata das normas; mapa de temas prioritários orienta a fiscalização.",r:"Res. CD/ANPD 30 e 31/2025"},
{id:"a25",d:"anpd",t:"ce",e:"Cebraspe",q:"Agentes de tratamento de pequeno porte têm prazo em dobro para comunicar incidentes de segurança à ANPD.",a:true,c:"Seis dias úteis, em vez de três.",r:"Res. CD/ANPD 15/2024"},
{id:"a26",d:"anpd",t:"ce",e:"Cebraspe",q:"Pelo regulamento do encarregado, a indicação de encarregado pelo operador é obrigatória.",a:false,c:"Para o operador é facultativa e considerada boa prática.",r:"Res. CD/ANPD 18/2024"},
{id:"a27",d:"anpd",t:"ce",e:"Cebraspe",q:"Startups podem ser enquadradas como agentes de tratamento de pequeno porte.",a:true,c:"Desde que não façam tratamento de alto risco nem superem os limites de receita.",r:"Res. CD/ANPD 2/2022"},
{id:"a28",d:"anpd",t:"ce",e:"Cebraspe",q:"Agentes de pequeno porte estão dispensados de manter qualquer registro das operações de tratamento.",a:false,c:"Eles mantêm registro simplificado.",r:"Res. CD/ANPD 2/2022"},
{id:"a29",d:"anpd",t:"ce",e:"Cebraspe",q:"A ANPD e os órgãos reguladores setoriais devem coordenar suas atividades nas esferas de atuação correspondentes.",a:true,c:"Coordenação para eficiência e funcionamento regular dos setores.",r:"LGPD, art. 55-J, §3º"},
{id:"a30",d:"anpd",t:"ce",e:"Cebraspe",q:"Os membros do Conselho Diretor da ANPD só perdem o cargo por renúncia, condenação judicial transitada em julgado ou demissão decorrente de processo administrativo disciplinar.",a:true,c:"Garantia de estabilidade no mandato.",r:"LGPD, art. 55-E"},
{id:"a31",d:"anpd",t:"me",e:"FGV",q:"Uma rede de academias usa reconhecimento facial na catraca. Para a Res. CD/ANPD 2/2022, esse tratamento tende a ser de alto risco porque:",o:["toda academia é empresa de grande porte.","envolve dado biométrico (sensível) e pode afetar significativamente direitos, combinando critério geral e específico.","biometria nunca pode ser tratada no Brasil.","a ANPD proíbe catracas eletrônicas.","o tratamento é feito por operador."],a:1,c:"Dado sensível é critério específico; afetar significativamente direitos ou larga escala é critério geral. Biometria está na agenda regulatória.",r:"Res. CD/ANPD 2/2022, art. 4º"},
{id:"r13",d:"reg",t:"ce",e:"Cebraspe",q:"As agências reguladoras devem elaborar relatório anual de atividades, encaminhado ao ministro da área, ao Senado, à Câmara e ao TCU.",a:true,c:"Instrumento de prestação de contas.",r:"Lei 13.848/2019, art. 15"},
{id:"r14",d:"reg",t:"ce",e:"Cebraspe",q:"O plano estratégico das agências reguladoras abrange período de quatro anos.",a:true,c:"Ao lado do plano de gestão e desempenho e da agenda regulatória.",r:"Lei 13.848/2019, art. 17"},
{id:"r15",d:"reg",t:"ce",e:"Cebraspe",q:"O processo de decisão das agências reguladoras referente à regulação tem caráter colegiado.",a:true,c:"Decisões pelo conselho diretor ou diretoria colegiada.",r:"Lei 13.848/2019, art. 7º"},
{id:"r16",d:"reg",t:"ce",e:"Cebraspe",q:"As reuniões deliberativas do conselho diretor das agências são sigilosas, para proteger a independência dos dirigentes.",a:false,c:"São públicas e gravadas em meio eletrônico, com exceções legais.",r:"Lei 13.848/2019, art. 8º"},
{id:"r17",d:"reg",t:"me",e:"FGV",q:"Bem cujo consumo por um indivíduo não reduz sua disponibilidade para os demais e do qual é difícil excluir quem não paga é denominado:",o:["bem de Giffen","bem público","bem inferior","bem de clube","bem posicional"],a:1,c:"Não rivalidade e não exclusão.",r:"Falhas de mercado"},
{id:"r18",d:"reg",t:"ce",e:"Cebraspe",q:"Externalidade negativa é o custo imposto a terceiros que não é refletido no preço da transação.",a:true,c:"Ex.: poluição; em dados, vazamentos que afetam terceiros.",r:"Falhas de mercado"},
{id:"r19",d:"reg",t:"ce",e:"Cebraspe",q:"Na regulação por preço-teto (price cap), a empresa retém ganhos de produtividade obtidos durante o período, o que incentiva a eficiência.",a:true,c:"Diferente da regulação por custo do serviço.",r:"Regulação por incentivos"},
{id:"r20",d:"reg",t:"ce",e:"Cebraspe",q:"Para promover a concorrência, as agências reguladoras e o CADE devem atuar em estreita cooperação.",a:true,c:"Capítulo de interação com órgãos de defesa da concorrência.",r:"Lei 13.848/2019, art. 25"},
{id:"c08",d:"const",t:"ce",e:"Cebraspe",q:"São invioláveis a intimidade, a vida privada, a honra e a imagem das pessoas, assegurado o direito a indenização pelo dano material ou moral decorrente de sua violação.",a:true,c:"Base constitucional da privacidade.",r:"CF, art. 5º, X"},
{id:"c09",d:"const",t:"ce",e:"Cebraspe",q:"Segundo a jurisprudência do STJ, não cabe habeas data se não houve recusa de informações por parte da autoridade administrativa.",a:true,c:"Súmula 2 do STJ.",r:"STJ, Súmula 2"},
{id:"c10",d:"const",t:"ce",e:"Cebraspe",q:"Todos têm direito a receber dos órgãos públicos informações de seu interesse particular ou coletivo, ressalvadas aquelas cujo sigilo seja imprescindível à segurança da sociedade e do Estado.",a:true,c:"Fundamento constitucional da LAI.",r:"CF, art. 5º, XXXIII"},
{id:"c11",d:"const",t:"ce",e:"Cebraspe",q:"Agências reguladoras podem ser criadas por decreto do Presidente da República.",a:false,c:"Autarquias só por lei específica.",r:"CF, art. 37, XIX"},
{id:"d11",d:"adm",t:"ce",e:"Cebraspe",q:"Concluída a instrução, a Administração tem até trinta dias para decidir, prorrogáveis por igual período expressamente motivado.",a:true,c:"Prazo do art. 49.",r:"Lei 9.784/1999, art. 49"},
{id:"d12",d:"adm",t:"ce",e:"Cebraspe",q:"Salvo disposição legal em contrário, o recurso administrativo tem efeito suspensivo.",a:false,c:"Regra: sem efeito suspensivo.",r:"Lei 9.784/1999, art. 61"},
{id:"d13",d:"adm",t:"ce",e:"Cebraspe",q:"Da decisão de recurso pode resultar agravamento da situação do recorrente, que deve ser cientificado para formular alegações antes da decisão.",a:true,c:"Reformatio in pejus é admitida no recurso.",r:"Lei 9.784/1999, art. 64"},
{id:"d14",d:"adm",t:"ce",e:"Cebraspe",q:"Da revisão do processo administrativo sancionador poderá resultar agravamento da sanção.",a:false,c:"Na revisão é vedado o agravamento.",r:"Lei 9.784/1999, art. 65"},
{id:"d15",d:"adm",t:"ce",e:"Cebraspe",q:"A avocação temporária de competência de órgão hierarquicamente inferior é permitida em caráter excepcional e por motivos relevantes devidamente justificados.",a:true,c:"Literalidade do art. 15.",r:"Lei 9.784/1999, art. 15"},
{id:"d16",d:"adm",t:"ce",e:"Cebraspe",q:"É impedido de atuar em processo administrativo o servidor que tenha interesse direto ou indireto na matéria.",a:true,c:"Impedimento do art. 18.",r:"Lei 9.784/1999, art. 18"},
{id:"d17",d:"adm",t:"me",e:"FGV",q:"O poder que permite ao chefe do Executivo expedir decretos para a fiel execução das leis é o poder:",o:["hierárquico","disciplinar","regulamentar","de polícia","vinculado"],a:2,c:"CF, art. 84, IV.",r:"Poderes administrativos"},
{id:"g11",d:"digital",t:"ce",e:"Cebraspe",q:"Pelo ECA Digital, as contas de crianças e adolescentes de até 16 anos em redes sociais devem estar vinculadas à conta de um responsável legal.",a:true,c:"Supervisão parental obrigatória.",r:"Lei 15.211/2025"},
{id:"g12",d:"digital",t:"ce",e:"Cebraspe",q:"O ECA Digital exige que produtos e serviços adotem, por padrão, a configuração no nível mais alto de proteção para crianças e adolescentes.",a:true,c:"Proteção por padrão (by default).",r:"Lei 15.211/2025"},
{id:"g13",d:"digital",t:"ce",e:"Cebraspe",q:"O ECA Digital permite o perfilamento de crianças para publicidade comercial direcionada, desde que haja consentimento dos pais.",a:false,c:"O perfilamento para publicidade direcionada a esse público é vedado.",r:"Lei 15.211/2025"},
{id:"g14",d:"digital",t:"ce",e:"Cebraspe",q:"As obrigações do ECA Digital substituem as da LGPD quanto aos dados de crianças e adolescentes.",a:false,c:"São complementares e se acumulam.",r:"Lei 15.211/2025; LGPD, art. 14"},
{id:"g15",d:"digital",t:"ce",e:"Cebraspe",q:"As sanções do ECA Digital incluem multa de até R$ 50 milhões por infração.",a:true,c:"Ao lado de advertência e suspensão de atividades.",r:"Lei 15.211/2025, art. 35"},
{id:"g16",d:"digital",t:"ce",e:"Cebraspe",q:"Na provisão de conexão à internet, é vedado guardar os registros de acesso a aplicações de internet.",a:true,c:"Separação entre conexão e aplicações.",r:"Lei 12.965/2014, art. 14"},
{id:"g17",d:"digital",t:"ce",e:"Cebraspe",q:"Pela LAI, o serviço de busca e fornecimento de informação é gratuito, podendo ser cobrado apenas o custo de reprodução de documentos.",a:true,c:"Isento quem declarar insuficiência econômica.",r:"Lei 12.527/2011, art. 12"},
{id:"g18",d:"digital",t:"ce",e:"Cebraspe",q:"O pedido de acesso à informação deve indicar os motivos da solicitação.",a:false,c:"São vedadas exigências relativas aos motivos.",r:"Lei 12.527/2011, art. 10, §3º"},
{id:"t11",d:"ti",t:"ce",e:"Cebraspe",q:"Phishing é ataque de engenharia social que induz a vítima a fornecer informações sensíveis por meio de mensagens fraudulentas.",a:true,c:"Principal vetor de incidentes.",r:"Ameaças"},
{id:"t12",d:"ti",t:"ce",e:"Cebraspe",q:"A criptografia simétrica é mais lenta que a assimétrica, por isso é usada apenas para a troca de chaves.",a:false,c:"É o contrário: a assimétrica é mais lenta e costuma proteger a troca da chave simétrica.",r:"Criptografia"},
{id:"t13",d:"ti",t:"ce",e:"Cebraspe",q:"A privacidade diferencial adiciona ruído calibrado aos resultados de consultas para limitar o que se pode inferir sobre um indivíduo.",a:true,c:"Técnica usada em estatísticas oficiais.",r:"Anonimização"},
{id:"t14",d:"ti",t:"ce",e:"Cebraspe",q:"Dados pseudonimizados deixam de ser dados pessoais para a LGPD.",a:false,c:"Continuam pessoais, pois a reidentificação é possível com informação adicional.",r:"LGPD, art. 13, §4º"},
{id:"t15",d:"ti",t:"ce",e:"Cebraspe",q:"No modelo SaaS, o cliente gerencia o sistema operacional das máquinas virtuais.",a:false,c:"Isso é IaaS. No SaaS o cliente só usa a aplicação.",r:"Computação em nuvem"},
{id:"t16",d:"ti",t:"ce",e:"Cebraspe",q:"Pelo princípio do menor privilégio, o usuário recebe apenas as permissões necessárias às suas funções.",a:true,c:"Liga-se ao princípio da necessidade da LGPD.",r:"Controle de acesso"},
{id:"t17",d:"ti",t:"ce",e:"Cebraspe",q:"Na tríade CID, a integridade garante que a informação esteja acessível quando necessária.",a:false,c:"Isso é disponibilidade. Integridade é não alteração indevida.",r:"Segurança da informação"},
{id:"t18",d:"ti",t:"ce",e:"Cebraspe",q:"Vieses nos dados de treinamento de modelos de aprendizado de máquina podem gerar decisões discriminatórias, o que se relaciona ao princípio da não discriminação da LGPD.",a:true,c:"Tema prioritário da ANPD (IA e decisões automatizadas).",r:"LGPD, art. 6º, IX"},
{id:"t19",d:"ti",t:"ce",e:"Cebraspe",q:"Ferramentas de DLP (data loss prevention) monitoram e bloqueiam a saída não autorizada de dados sensíveis.",a:true,c:"Controle preventivo contra vazamentos.",r:"Segurança da informação"},
{id:"p08",d:"port",t:"ce",e:"Cebraspe",q:"A frase “Vende-se imóveis” está de acordo com a norma-padrão.",a:false,c:"Voz passiva sintética: “Vendem-se imóveis”.",r:"Concordância verbal"},
{id:"p09",d:"port",t:"ce",e:"Cebraspe",q:"Em “Precisa-se de analistas”, o verbo deveria estar no plural para concordar com “analistas”.",a:false,c:"Verbo transitivo indireto + se: fica no singular.",r:"Concordância verbal"},
{id:"p10",d:"port",t:"ce",e:"Cebraspe",q:"Em “A norma visa ao interesse público”, o verbo visar, no sentido de objetivar, rege a preposição “a”.",a:true,c:"Visar (objetivar) é transitivo indireto.",r:"Regência verbal"},
{id:"p11",d:"port",t:"ce",e:"Cebraspe",q:"Em “Os agentes que tratam dados sensíveis devem adotar salvaguardas”, a oração adjetiva é restritiva e, por isso, não vem entre vírgulas.",a:true,c:"Com vírgulas seria explicativa e mudaria o sentido.",r:"Pontuação"},
{id:"p12",d:"port",t:"me",e:"FGV",q:"Em “A sanção foi mantida, porquanto houve reincidência”, o conectivo “porquanto” expressa:",o:["concessão","causa","finalidade","condição","proporção"],a:1,c:"Porquanto = porque, visto que.",r:"Conectivos"},
{id:"i06",d:"ing",t:"ce",e:"Cebraspe",q:"The expression “data subject” corresponds, in the LGPD, to titular dos dados.",a:true,c:"Termo do GDPR.",r:"Vocabulary"},
{id:"i07",d:"ing",t:"ce",e:"Cebraspe",q:"In “The authority imposed a fine”, the word “fine” means multa.",a:true,c:"Fine = multa (substantivo).",r:"Vocabulary"},
{id:"i08",d:"ing",t:"ce",e:"Cebraspe",q:"The verb “to pretend” means pretender.",a:false,c:"Pretend = fingir. Pretender = to intend.",r:"False friends"},
{id:"i09",d:"ing",t:"ce",e:"Cebraspe",q:"In “Unless consent is given, processing is unlawful”, “unless” is equivalent to a menos que.",a:true,c:"Unless = if not.",r:"Connectors"},
{id:"e06",d:"etica",t:"ce",e:"Cebraspe",q:"Pelo Código de Ética do servidor federal, é dever ser assíduo e frequente ao serviço.",a:true,c:"A ausência injustificada causa dano ao trabalho ordenado.",r:"Decreto 1.171/1994, XIV, l"},
{id:"e07",d:"etica",t:"ce",e:"Cebraspe",q:"A ocorrência de conflito de interesses depende de lesão ao patrimônio público.",a:false,c:"Independe de lesão ou do recebimento de vantagem.",r:"Lei 12.813/2013, art. 4º, §2º"},
{id:"e08",d:"etica",t:"ce",e:"Cebraspe",q:"Pela Lei 8.112/1990, é proibido ao servidor recusar fé a documentos públicos.",a:true,c:"Proibição do art. 117.",r:"Lei 8.112/1990, art. 117, III"},
{id:"e09",d:"etica",t:"ce",e:"Cebraspe",q:"O abandono de cargo é hipótese de demissão do servidor público federal.",a:true,c:"Rol do art. 132.",r:"Lei 8.112/1990, art. 132, II"}
);

